#!/usr/bin/env bash
set -euo pipefail

echo "================================================"
echo " LocalLLMChat - Linux local build"
echo "================================================"
echo

# Optional: stamp a version. Usage: ./build_linux.sh 1.4.0
VERSION="${1:-}"
if [[ -n "$VERSION" ]]; then
    echo "Stamping version: v${VERSION}"
    cat > lib/version.dart <<EOF
/// Auto-generated by local build script. Do not edit by hand.
const String kAppVersion = 'v${VERSION} (local)';
EOF
    echo
fi

echo "Fetching dependencies..."
flutter pub get

echo
echo "Building release..."
if [[ -n "$VERSION" ]]; then
    flutter build linux --release --build-name="$VERSION" --build-number=0
else
    flutter build linux --release
fi

OUTPUT="build/linux/x64/release/bundle"

# Optional: package into a tar.gz next to the build folder.
if [[ -n "$VERSION" ]]; then
    ARCHIVE="build/LocalLLMChat-v${VERSION}-linux.tar.gz"
    echo
    echo "Packaging → ${ARCHIVE}"
    tar -czf "$ARCHIVE" -C "$(dirname "$OUTPUT")" "$(basename "$OUTPUT")"
    echo "Archive:  $ARCHIVE"
fi

echo
echo "================================================"
echo " Build complete!"
echo " Output:  ${OUTPUT}"
echo "================================================"
